// spec: .qa/e2e/specs/match-mutual.md 1.3 · кейс .qa/tests/match-mutual/MATCH-03.md
import { test, expect } from '../../fixtures';
import { captureApi, rpc } from '../_shared/api';
import { saveSession } from '../_shared/session';

test.describe('Взаимный матч (сервер)', () => {
  test('Like самому себе отклоняется (400) @iphone @data (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    await free.setViewportSize({ width: 390, height: 844 });
    try {
      const a = await captureApi(free);
      const res = await rpc(a, 'swipe', { p_target: a.userId, p_kind: 'like' });
      expect(res.status(), await res.text()).toBe(400);
    } finally {
      await saveSession(free, 'free');
    }
  });
});
